            if ((emon.Port.CellsAt(gfl, (i * 16) + 1) > emon.Port.CellsAt(gfl, (i * 16) + 3)) || (emon.Port.CellsAt(gfl, (i * 16) + 2) > emon.Port.CellsAt(gfl, (i * 16) + 4))) {
