            }
            if (GlRunOk(emon.Port.CellsAt(ggp, (i * 12) + 6), emon.Port.CellsAt(ggp, (i * 12) + 7), nrf) == 0) {
                return 3;
            }
            v = emon.Port.CellsAt(ggp, (i * 12) + 1);
            if ((v < 1) || (v > 3)) {
                return 3;
            }
            i += 1;
        }
        i = 0;
        while (i < nc) {
            v = emon.Port.CellsAt(grg, (i * 16) + 5);
            if ((v < 1) || (v > 3)) {
                return 5;
            }
            v = emon.Port.CellsAt(grg, (i * 16) + 7);
            w = emon.Port.CellsAt(grg, (i * 16) + 8);
            if ((v < 0) && (w >= 0)) {
                return 5;
            }
            if ((v >= 0) && (w < 0)) {
                return 5;
            }
            if ((emon.Port.CellsAt(grg, (i * 16) + 1) > emon.Port.CellsAt(grg, (i * 16) + 3)) || (emon.Port.CellsAt(grg, (i * 16) + 2) > emon.Port.CellsAt(grg, (i * 16) + 4))) {
                return 4;
            }
            i += 1;
        }
        i = 0;
        while (i < nrf) {
            v = emon.Port.CellsAt(refs, i * 2);
            w = emon.Port.CellsAt(refs, (i * 2) + 1);
            if (v == 41) {
                if ((w < 0) || (w >= nr)) {
                    return 6;
                }
            }
            if (v == 43) {
                if ((w < 0) || (w >= nf)) {
                    return 6;
                }
            }
            if (v == 44) {
