    internal static int GlBegin(System.Text.StringBuilder t, int pr, int started, int code) {
        if (started == 1) {
            emon.Port.TextAscii(t, ",");
        }
        if (pr == 1) {
            Json.JsIndent(t, 3);
        }
        emon.Port.TextAscii(t, "\"");
        GlkEmitName(t, code);
        emon.Port.TextAscii(t, "\":");
        if (pr == 1) {
            emon.Port.TextAscii(t, " ");
        }
        return 1;
    }
    internal static int GlBits(System.Text.StringBuilder t, int pr, int v, int which) {
        // A bit set as an array of names (which 10 `gq`, 11 `gqf`, 12 `gs`).
        int b = 0;
        int k = 0;
        int bit = 1;
        emon.Port.TextAscii(t, "[");
        while (b < 16) {
            if ((v & bit) != 0) {
                Json.JsFsep(t, pr, k);
                emon.Port.TextAscii(t, "\"");
                if (which == 10) {
                    GqEmitName(t, bit);
                }
                if (which == 11) {
                    GqfEmitName(t, bit);
                }
                if (which == 12) {
                    GsEmitName(t, bit);
                }
                emon.Port.TextAscii(t, "\"");
                k += 1;
            }
            bit *= 2;
            b += 1;
        }
        emon.Port.TextAscii(t, "]");
        return 0;
    }
    internal static int GlField(System.Text.StringBuilder t, int pr, emon.Port.Cells c, int stride, int row, int r, int started) {
        // One printed field of a row, by row `r` of `gl-fd`.
        int f = GlFd[r * 6 + 1];
        int kind = GlFd[r * 6 + 2];
        int key = GlFd[r * 6 + 3];
        int dflt = GlFd[r * 6 + 4];
        int arg = GlFd[r * 6 + 5];
        int p = (row * stride) + f;
        int s = started;
        if (((kind == 1) || ((kind == 2) || (((kind >= 6) && (kind <= 9)) || (kind >= 10)))) && (emon.Port.CellsAt(c, p) == dflt)) {
            return started;
        }
        if (kind == 1) {
            s = GlBegin(t, pr, s, key);
            emon.Port.TextI32(t, emon.Port.CellsAt(c, p));
            return s;
        }
        if (kind == 2) {
            s = GlBegin(t, pr, s, key);
            Json.JsCpt(t, emon.Port.CellsAt(c, p));
            return s;
        }
        if (kind == 3) {
            s = GlBegin(t, pr, s, key);
            emon.Port.TextAscii(t, "[");
            Json.JsCpt(t, emon.Port.CellsAt(c, p));
            Json.JsFsep(t, pr, 1);
            Json.JsCpt(t, emon.Port.CellsAt(c, p + 1));
            Json.JsFsep(t, pr, 1);
            Json.JsCpt(t, emon.Port.CellsAt(c, p + 2));
            Json.JsFsep(t, pr, 1);
            Json.JsCpt(t, emon.Port.CellsAt(c, p + 3));
            emon.Port.TextAscii(t, "]");
            return s;
        }
        if (kind == 4) {
            if ((emon.Port.CellsAt(c, p) == dflt) && (emon.Port.CellsAt(c, p + 1) == arg)) {
                return started;
            }
            s = GlBegin(t, pr, s, key);
            emon.Port.TextAscii(t, "[");
            emon.Port.TextI32(t, emon.Port.CellsAt(c, p));
            Json.JsFsep(t, pr, 1);
            emon.Port.TextI32(t, emon.Port.CellsAt(c, p + 1));
            emon.Port.TextAscii(t, "]");
            return s;
        }
        if (kind == 5) {
            if (emon.Port.CellsAt(c, p + 1) == dflt) {
                return started;
            }
            s = GlBegin(t, pr, s, key);
            emon.Port.TextAscii(t, "[\"");
            Evidence.EaEmitName(t, emon.Port.CellsAt(c, p));
            emon.Port.TextAscii(t, "\",");
            if (pr == 1) {
                emon.Port.TextAscii(t, " ");
            }
            emon.Port.TextI32(t, emon.Port.CellsAt(c, p + 1));
            emon.Port.TextAscii(t, "]");
            return s;
        }
        if ((kind >= 6) && (kind <= 9)) {
            s = GlBegin(t, pr, s, key);
            emon.Port.TextAscii(t, "\"");
            if (kind == 6) {
                GoEmitName(t, emon.Port.CellsAt(c, p));
            }
            if (kind == 7) {
                Evidence.RsEmitName(t, emon.Port.CellsAt(c, p));
            }
            if (kind == 8) {
                GkEmitName(t, emon.Port.CellsAt(c, p));
            }
            if (kind == 9) {
                RkEmitName(t, emon.Port.CellsAt(c, p));
            }
            emon.Port.TextAscii(t, "\"");
            return s;
        }
        if (kind >= 10) {
            s = GlBegin(t, pr, s, key);
            GlBits(t, pr, emon.Port.CellsAt(c, p), kind);
            return s;
        }
        return started;
    }
    internal static int GlRow(System.Text.StringBuilder t, int pr, int a, emon.Port.Cells c, int row) {
        // One row of arena a (1 `grl` .. 4 `grg`) as an object, its fields in stride order.
        int first = GlFx[(a - 1) * 4 + 0];
        int cnt = GlFx[(a - 1) * 4 + 1];
        int stride = GlFx[(a - 1) * 4 + 2];
        int s = 0;
        int k = 0;
        emon.Port.TextAscii(t, "{");
        while (k < cnt) {
            s = GlField(t, pr, c, stride, row, first + k, s);
            k += 1;
        }
        Json.JsClose(t, pr, 2, s);
        return 0;
    }
    public static int GlArena(System.Text.StringBuilder t, int pr, int started, int a, emon.Port.Cells c) {
        // `"key":[row, ...]` for arena a (1 `grl`, 2 `gfl`, 3 `ggp`, 4 `grg`), as a member of the dump's object; answers 1.
        int stride = GlFx[(a - 1) * 4 + 2];
        int n = emon.Port.CellsLen(c) / stride;
        int i = 0;
        if (started == 1) {
            emon.Port.TextAscii(t, ",");
        }
        if (pr == 1) {
            Json.JsIndent(t, 1);
        }
        emon.Port.TextAscii(t, "\"");
        GlkEmitName(t, a);
        emon.Port.TextAscii(t, "\":");
        if (pr == 1) {
            emon.Port.TextAscii(t, " ");
        }
        emon.Port.TextAscii(t, "[");
        while (i < n) {
            Json.JsAelem(t, pr, 1, i);
            GlRow(t, pr, a, c, i);
            i += 1;
        }
        Json.JsAend(t, pr, 1, n);
        return 1;
    }
    public static int GlEmit(System.Text.StringBuilder t, int pretty, int s0, emon.Port.Cells grl, emon.Port.Cells gfl, emon.Port.Cells ggp, emon.Port.Cells grg) {
        // The four arrays as members of the dump's object, `s0` being 1 when a member came before. Answers 1.
        int s = s0;
        s = GlArena(t, pretty, s, 1, grl);
        s = GlArena(t, pretty, s, 2, gfl);
        s = GlArena(t, pretty, s, 3, ggp);
        s = GlArena(t, pretty, s, 4, grg);
        return s;
    }
